function D(t,e,n=5){if(Array.isArray(e))return e;const r=t.filter(f=>typeof f=="number"&&isFinite(f)).sort((f,l)=>f-l);if(r.length===0)return[];const c=r[0],i=r[r.length-1];if(c===i)return[c,i];switch(e){case"equal":return w(c,i,n);case"quantile":return A(r,n);case"jenks":return B(r,n);case"logarithmic":return j(r,n);case"stddev":return q(r,n);case"geometric":return v(r,n);case"arithmetic":return I(r,n);case"headtail":return m(r,n);default:return[]}}function w(t,e,n){const r=(e-t)/n,c=[t];for(let i=1;i<n;i++)c.push(t+r*i);return c.push(e),c}function A(t,e){const n=t.length,r=t[0],c=t[n-1],i=[r];for(let f=1;f<e;f++){const l=(n-1)*(f/e),o=Math.floor(l),h=l-o;i.push(t[o+1]!==void 0?t[o]+h*(t[o+1]-t[o]):t[o])}return i.push(c),i}function B(t,e){const n=b(t,e);return[t[0],...n,t[t.length-1]]}function b(t,e){const n=t.length,r=Array.from({length:n+1},()=>new Array(e+1).fill(0)),c=Array.from({length:n+1},()=>new Array(e+1).fill(0));for(let o=1;o<=e;o++){r[1][o]=1,c[1][o]=0;for(let h=2;h<=n;h++)c[h][o]=1/0}let i=0;for(let o=2;o<=n;o++){let h=0,a=0,u=0;for(let p=1;p<=o;p++){const M=o-p+1,x=t[M-1];a+=x*x,h+=x,u++,i=a-h*h/u;const k=M-1;if(k!==0)for(let s=2;s<=e;s++)c[o][s]>=i+c[k][s-1]&&(r[o][s]=M,c[o][s]=i+c[k][s-1])}r[o][1]=1,c[o][1]=i}const f=new Array(e+1);f[e]=t[n-1],f[0]=t[0];let l=n;for(let o=e;o>=2;o--){const h=r[l][o]-2;f[o-1]=t[h],l=r[l][o]-1}return f.slice(1,e)}function j(t,e){const n=t[0],r=t[t.length-1],c=n<=0?-n+1:0,i=Math.log10(n+c),l=(Math.log10(r+c)-i)/e,o=[n];for(let h=1;h<e;h++){const a=Math.pow(10,i+l*h)-c;o.push(a)}return o.push(r),o}function q(t,e){const n=t.length,r=t[0],c=t[n-1],i=t.reduce((a,u)=>a+u,0)/n,f=t.reduce((a,u)=>a+(u-i)**2,0)/n,l=Math.sqrt(f);if(l===0)return w(r,c,e);const o=[r],h=Math.floor(e/2);if(e%2===1)for(let a=-h;a<=h;a++){if(a===0)continue;const u=i+a*l;u>r&&u<c&&o.push(u)}else for(let a=-h;a<=h-1;a++){const u=i+a*l;u>r&&u<c&&o.push(u)}return o.push(c),o.sort((a,u)=>a-u),y(o)}function v(t,e){const n=t[0],r=t[t.length-1],c=n<=0?-n+1:0,i=n+c,f=r+c;if(i<=0||f<=0)return w(n,r,e);const l=Math.pow(f/i,1/e),o=[n];for(let h=1;h<e;h++)o.push(i*Math.pow(l,h)-c);return o.push(r),o}function I(t,e){const n=t[0],r=t[t.length-1],i=2*(r-n)/(e*(e+1)),f=[n];let l=n;for(let o=1;o<e;o++)l+=i*o,f.push(l);return f.push(r),f}function m(t,e){const n=[t[0]];let r=t.slice();for(;r.length>0&&n.length<e;){const c=r.reduce((f,l)=>f+l,0)/r.length,i=r.filter(f=>f>c);if(i.length===0)break;if(i.length/r.length<.4)n.push(c),r=i;else break}return n.push(t[t.length-1]),y(n)}function y(t){const e=[];for(const n of t)(e.length===0||n>e[e.length-1])&&e.push(n);return e}function E(t,e){if(e.length<2)return 0;for(let n=1;n<e.length;n++)if(t<=e[n])return n-1;return e.length-2}const g=[1,1.5,2,2.5,3,4,5,6,7,8,10];function N(t){if(t===0)return 0;const e=t<0?-1:1,n=Math.abs(t),r=Math.pow(10,Math.floor(Math.log10(n))),c=n/r;let i=g[0],f=Math.abs(c-i);for(let l=1;l<g.length;l++){const o=Math.abs(c-g[l]);o<f&&(i=g[l],f=o)}return e*i*r}function z(t){if(t===0)return g[0];const e=t<0?-1:1,n=Math.abs(t),r=Math.pow(10,Math.floor(Math.log10(n))),c=n/r;for(const i of g)if(i>c+1e-9)return e*i*r;return e*g[0]*r*10}function F(t){if(!Array.isArray(t)||t.length<3)return t;const e=t.length-1,n=t[e],r=[t[0]];for(let c=1;c<e;c++){const i=r[c-1];let f=N(t[c]);f<=i&&(f=z(i)),f>=n&&(t[c]>i&&t[c]<n?f=t[c]:f=(i+n)/2),r.push(f)}return r.push(n),r}export{D as calculateBreaks,E as getClassIndex,F as makeBreaksPretty};
